package compatibility

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	"github.com/vaultys/vaultysid/go/pkg/challenger"
	"github.com/vaultys/vaultysid/go/pkg/vaultysid"
)

// securityV2Vectors mirrors testdata/security-v2-vectors.json, generated by
// typescript/test/interops/generate-security-v2-vectors.ts.
type securityV2Vectors struct {
	Identities map[string]struct {
		Entropy   string `json:"entropy"`
		Type      int    `json:"type"`
		Algorithm string `json:"algorithm"`
		ID        string `json:"id"`
		DID       string `json:"did"`
		Secret    string `json:"secret"`
	} `json:"identities"`
	Handshake struct {
		Complete        string `json:"complete"`
		UnsignedBytes   string `json:"unsignedBytes"`
		HandshakeDigest string `json:"handshakeDigest"`
		Sign1           string `json:"sign1"`
		Sign2           string `json:"sign2"`
	} `json:"handshake"`
	DHIESV2 struct {
		Sender     string `json:"sender"`
		Recipient  string `json:"recipient"`
		Plaintext  string `json:"plaintext"`
		Ciphertext string `json:"ciphertext"`
	} `json:"dhiesV2"`
	RawSignature struct {
		Signer     string `json:"signer"`
		MessageHex string `json:"messageHex"`
		Signature  string `json:"signature"`
	} `json:"rawSignature"`
	SignChallenge struct {
		Signer     string `json:"signer"`
		MessageHex string `json:"messageHex"`
		Signature  string `json:"signature"`
	} `json:"signChallenge"`
}

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("bad hex %q: %v", s, err)
	}
	return b
}

// TestSecurityV2Vectors checks the Go implementation against the TypeScript
// reference for the 4.0.0 security spec: identity derivation, handshake
// certificate, DHIES v2 and the VAULTYS_RAW / VAULTYS_SIGN signature domains.
func TestSecurityV2Vectors(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("testdata", "security-v2-vectors.json"))
	if err != nil {
		t.Fatal(err)
	}
	var v securityV2Vectors
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatalf("invalid vectors JSON: %v", err)
	}

	ids := map[string]*vaultysid.VaultysID{}
	t.Run("identities", func(t *testing.T) {
		for name, ident := range v.Identities {
			id, err := vaultysid.FromEntropy(mustHex(t, ident.Entropy), vaultysid.IdentityType(ident.Type))
			if err != nil {
				t.Fatalf("%s: FromEntropy: %v", name, err)
			}
			if got := hex.EncodeToString(id.ToBytes()); got != ident.ID {
				t.Fatalf("%s: id mismatch\n got %s\nwant %s", name, got, ident.ID)
			}
			if got := id.DID(); got != ident.DID {
				t.Fatalf("%s: did mismatch: got %s want %s", name, got, ident.DID)
			}
			fromSecret, err := vaultysid.FromSecret(mustHex(t, ident.Secret))
			if err != nil {
				t.Fatalf("%s: FromSecret: %v", name, err)
			}
			if !bytes.Equal(fromSecret.ToBytes(), id.ToBytes()) {
				t.Fatalf("%s: secret does not restore the same id", name)
			}
			ids[name] = fromSecret
		}
	})

	t.Run("handshake", func(t *testing.T) {
		ch, err := challenger.VerifyCertificate(mustHex(t, v.Handshake.Complete))
		if err != nil {
			t.Fatalf("TS handshake certificate rejected: %v", err)
		}
		unsigned, err := challenger.SerializeUnsigned(ch)
		if err != nil {
			t.Fatal(err)
		}
		if !bytes.Equal(unsigned, mustHex(t, v.Handshake.UnsignedBytes)) {
			t.Fatalf("unsigned bytes differ from TS:\n got %x\nwant %s", unsigned, v.Handshake.UnsignedBytes)
		}
		if !bytes.Equal(ch.Sign1, mustHex(t, v.Handshake.Sign1)) || !bytes.Equal(ch.Sign2, mustHex(t, v.Handshake.Sign2)) {
			t.Fatal("decoded signatures differ from vector")
		}
		id1, _ := vaultysid.FromID(ch.PK1, nil)
		id2, _ := vaultysid.FromID(ch.PK2, nil)
		if id1.VerifyHandshake(unsigned, ch.Sign1) != nil || id2.VerifyHandshake(unsigned, ch.Sign2) != nil {
			t.Fatal("VerifyHandshake failed on TS signatures")
		}
		// Handshake signatures must not verify in the other domains.
		if id1.VerifyChallenge(unsigned, ch.Sign1) == nil || id1.Verify(unsigned, ch.Sign1) == nil {
			t.Fatal("handshake signature verified outside VAULTYS_HANDSHAKE_V1")
		}
	})

	t.Run("dhies", func(t *testing.T) {
		recipient, sender := ids[v.DHIESV2.Recipient], ids[v.DHIESV2.Sender]
		if recipient == nil || sender == nil {
			t.Fatal("dhies identities missing")
		}
		senderPub, err := vaultysid.FromID(sender.ToBytes(), nil)
		if err != nil {
			t.Fatal(err)
		}
		pt, err := recipient.DHIESDecrypt(mustHex(t, v.DHIESV2.Ciphertext), senderPub)
		if err != nil {
			t.Fatalf("DHIES v2 decrypt of TS ciphertext failed: %v", err)
		}
		if string(pt) != v.DHIESV2.Plaintext {
			t.Fatalf("plaintext mismatch: %q", pt)
		}
		// Claiming the wrong sender must fail.
		if _, err := recipient.DHIESDecrypt(mustHex(t, v.DHIESV2.Ciphertext), recipient); err == nil {
			t.Fatal("DHIES v2 accepted a ciphertext under the wrong sender")
		}
	})

	t.Run("raw", func(t *testing.T) {
		signer := ids[v.RawSignature.Signer]
		msg := mustHex(t, v.RawSignature.MessageHex)
		sig := mustHex(t, v.RawSignature.Signature)
		if err := signer.Verify(msg, sig); err != nil {
			t.Fatalf("VAULTYS_RAW signature rejected: %v", err)
		}
		if signer.VerifyHandshake(msg, sig) == nil {
			t.Fatal("VAULTYS_RAW signature must not verify as handshake")
		}
	})

	t.Run("signChallenge", func(t *testing.T) {
		signer := ids[v.SignChallenge.Signer]
		msg := mustHex(t, v.SignChallenge.MessageHex)
		sig := mustHex(t, v.SignChallenge.Signature)
		if err := signer.VerifyChallenge(msg, sig); err != nil {
			t.Fatalf("VAULTYS_SIGN signature rejected: %v", err)
		}
		if signer.VerifyHandshake(msg, sig) == nil {
			t.Fatal("VAULTYS_SIGN signature must not verify as handshake")
		}
	})
}
